// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title IResultsRegistry
/// @notice Per-game results of the real-world competition, anchored to LocalTruth attestations.
///
///         The scores are the unit that decides the winner (sets in volleyball); partial scores
///         (set by set) stay in the attested file, which `sourceHash` points to. Each game carries
///         its format, so another head-to-head sport needs no change here.
interface IResultsRegistry {
    enum GameStatus {
        None, // never registered
        Scheduled, // registered, no result yet
        Final, // played, attested result
        Forfeit, // decided by forfeit
        Void // cancelled / not played (attested) or voided by the steward
    }

    /// @dev Draw is 3 so that every side fits in the 2 bits per game Predictions packs picks into.
    enum Side {
        None,
        Home,
        Away,
        Draw
    }

    /// @notice Fixture data, registered before the game can be used in a round.
    ///         The format says how a result is checked:
    ///           targetScore N   the winner is the first side to reach N (volleyball: 3 sets)
    ///           targetScore 0   open score: the side ahead wins
    ///           drawAllowed     an open score may end level (Side.Draw)
    struct GameInfo {
        bytes32 gameId; // keccak256(bytes(canonicalGameId))
        bytes32 homeTeam; // team (or player) code as a bytes32 short string
        bytes32 awayTeam;
        uint64 startTime; // unix seconds (UTC)
        uint8 targetScore; // 0: open score; N: the winner is the first side to reach N
        bool drawAllowed; // only with an open score
    }

    /// @notice A result read from an attested MSC file.
    struct ResultInput {
        bytes32 gameId;
        bytes32 homeTeam; // must match the registered fixture (guards against a home/away swap)
        bytes32 awayTeam;
        GameStatus status; // Final | Forfeit | Void
        Side winner;
        uint16 homeScore;
        uint16 awayScore;
        uint8 extraPeriods; // periods past regulation, where the sport has them (never with a target)
        bytes32 sourceHash; // SHA-256 of the attested public file (decoded from base64 sha256_pub)
        string attestationId; // LocalTruth competition_id the file was attested under
    }

    struct Game {
        bytes32 homeTeam;
        bytes32 awayTeam;
        uint64 startTime;
        uint64 recordedAt; // 0 while no result; set again by a correction
        GameStatus status;
        Side winner;
        uint16 homeScore;
        uint16 awayScore;
        uint8 extraPeriods;
        uint8 targetScore;
        bool drawAllowed;
        bytes32 sourceHash; // the attestation id is in the ResultRecorded / ResultCorrected event
        uint64 correctableUntil; // set with the result (recordedAt + correctionWindow); 0 once corrected
        bool corrected; // the steward corrected the result: it can never change again
    }

    function getGame(bytes32 gameId) external view returns (Game memory);

    /// @notice Whether the game has a result (or was voided). The steward may still correct it once,
    ///         until `correctableUntil`.
    function hasResult(bytes32 gameId) external view returns (bool);

    /// @notice Until when the steward may correct the game's result: 0 while it has no result or
    ///         once it was corrected, after which the result never changes. Fixed when the result
    ///         is written, so a later change of the correction window never reopens it.
    function correctableUntil(bytes32 gameId) external view returns (uint64);

    /// @notice Compact view (one slot) used by Predictions to schedule and settle rounds.
    ///         `recordedAt` is 0 until the game has a result or was voided.
    function outcomeOf(
        bytes32 gameId
    ) external view returns (GameStatus status, Side winner, uint64 startTime, uint64 recordedAt);
}

project/contracts/libraries/PicksLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title PicksLib
/// @notice Picks schema 1 (scoring layer 0): one byte per game, in the round's game order,
///         1 = home wins, 2 = away wins, 3 = draw (the values of IResultsRegistry.Side).
///         Every game must be picked. A draw pick is accepted on any game: where the registry
///         does not allow draws it can never match the outcome, and the app does not offer it.
///         On-chain, picks and round outcomes are packed 2 bits per game into a uint64
///         (max 32 games); outcome 0 means "game not counted" (void, or played before the lock).
library PicksLib {
    uint8 internal constant HOME = 1;
    uint8 internal constant AWAY = 2;
    uint8 internal constant DRAW = 3;

    /// @return ok false if any pick is not HOME/AWAY/DRAW
    function pack(bytes calldata picks) internal pure returns (bool ok, uint64 packed) {
        for (uint256 i = 0; i < picks.length; ++i) {
            uint8 p = uint8(picks[i]);
            if (p < HOME || p > DRAW) return (false, 0);
            packed |= uint64(p) << uint8(2 * i); // callers bound picks.length to 32
        }
        return (true, packed);
    }

    function unpack(uint64 packed, uint256 count) internal pure returns (bytes memory picks) {
        picks = new bytes(count);
        for (uint256 i = 0; i < count; ++i) {
            picks[i] = bytes1(pickAt(packed, i));
        }
    }

    function pickAt(uint64 packed, uint256 i) internal pure returns (uint8) {
        return uint8((packed >> (2 * i)) & 3);
    }

    /// @notice Layer-0 score: +1 per correct pick on a counted game.
    function score(
        uint64 picks,
        uint64 outcomes,
        uint256 count
    ) internal pure returns (uint8 correct, uint8 counted) {
        for (uint256 i = 0; i < count; ++i) {
            uint8 o = pickAt(outcomes, i);
            if (o == 0) continue;
            ++counted;
            if (pickAt(picks, i) == o) ++correct;
        }
    }

    function countedGames(uint64 outcomes, uint256 count) internal pure returns (uint8 counted) {
        for (uint256 i = 0; i < count; ++i) {
            if (pickAt(outcomes, i) != 0) ++counted;
        }
    }
}

